import itertools

def is_good(matrix, n):
    # Check if there exist r_i, c_j such that matrix[i][j] + r_i + c_j = 0
    # This is equivalent to matrix[i][j] = R_i + C_j
    # We can pick R_0 = 0, then C_j = matrix[0][j], and then R_i = matrix[i][0] - C_0
    # Then check if all matrix[i][j] = R_i + C_j
    R = [0] * n
    C = [0] * n

    # Let's try setting R[0] = 0
    C[0] = 0 # This is just a dummy
    # Let's use the property: matrix[i][j] - matrix[i][0] = matrix[0][j] - matrix[0][0]
    # or matrix[i][j] = matrix[i][0] + matrix[0][j] - matrix[0][0]
    for i in range(n):
        for j in range(n):
            if matrix[i][j] != matrix[i][0] + matrix[0][j] - matrix[0][0]:
                return False
    return True

def solve_small(n):
    import itertools
    elements = list(range(1, n*n + 1))
    count = 0
    for p in itertools.permutations(elements):
        matrix = []
        for i in range(n):
            matrix.append(list(p[i*n : (i+1)*n]))
        if is_good(matrix, n):
            count += 1
    return count

for n in range(2, 5):
