import itertools

def get_base_matrices(n):
    elements = list(range(1, n*n + 1))
    is_good_matrix = []
    for p in itertools.permutations(elements):
        matrix = []
        for i in range(n):
            matrix.append(list(p[i*n : (i+1)*n]))

        # Check if good
        is_good = True
        for i in range(n-1):
            for j in range(n-1):
                if matrix[i][j] + matrix[i+1][j+1] != matrix[i][j+1] + matrix[i+1][j]:
                    is_good = False
                    break
            if not is_good: break

        if is_good:
            is_good_matrix.append(tuple(map(tuple, matrix)))

    # Now find base matrices by grouping those that are row/column permutations of each other
    base_matrices = []
    seen = set()

    for m in is_good_matrix:
        if m in seen:
            continue

        # Find all row/column permutations of m
        perms = set()
        for r_p in itertools.permutations(range(n)):
            for c_p in itertools.permutations(range(n)):
                new_m = []
                for i in range(n):
                    row = []
                    for j in range(n):
                        row.append(m[r_p[i]][c_p[j]])
                    new_m.append(tuple(row))
                perms.add(tuple(new_m))

        base_matrices.append(m)
        seen.update(perms)

    return base_matrices

